// src/index.js

import store from './store';
import React from 'react';
import { render } from 'react-dom';
import { Provider } from 'react-redux';
import App from './containers/';
import './unit/const';
import './control';
import { subscribeRecord } from './unit';
import actions from './actions';
import {
  loadYandexHighScore,
  saveYandexScore,
  fetchYandexLeaderboard,
  showFullscreenAd,
  showVkInviteBox,
  getPlatform,
  logPlatform,
  initYandexSdk,
  showBannerAd,
} from './unit/yandexSdk';
import { syncYandexAchievements } from './unit/yandexSdk';
import { loadTotalScore } from './unit/yandexSdk';

// ===== ГЛОБАЛЬНЫЙ ОБРАБОТЧИК ОШИБОК (для отладки) =====
window.onerror = function(message, source, lineno, colno, error) {
  var errorDiv = document.createElement('div');
  errorDiv.style.cssText =
    'position:fixed;top:0;left:0;right:0;background:red;color:white;padding:20px;z-index:9999;font-size:16px;white-space:pre-wrap;word-break:break-all;';
  errorDiv.textContent = 'Ошибка: ' + message + '\n' + (error ? error.stack : '');
  document.body.appendChild(errorDiv);
  console.error('Глобальная ошибка:', message, error);
};

console.log('🔥 index.js ЗАГРУЖЕН!');

// Определяем платформу (безопасно)
var PLATFORM = getPlatform();
logPlatform();

// Глобальные функции для лидерборда
window.openLeaderboard = fetchYandexLeaderboard;

// Рендерим React немедленно (до синхронизации данных)
console.log('🚀 Рендерим React-приложение...');
try {
  render(
    React.createElement(Provider, { store: store },
      React.createElement(App, null)
    ),
    document.getElementById('root')
  );
} catch (e) {
  console.error('Ошибка рендеринга:', e);
  document.getElementById('root').innerHTML =
    '<pre style="color:red;font-size:20px;">Ошибка рендеринга: ' + e.message + '\n' + e.stack + '</pre>';
}

// ===== АСИНХРОННАЯ ИНИЦИАЛИЗАЦИЯ (с защитой от ошибок) =====
setTimeout(function() {
  console.log('⏳ Асинхронная инициализация...');
  try {
    var isVk = typeof vkBridge !== 'undefined' && PLATFORM === 'vk';
    var initPromise;
    if (isVk) {
      initPromise = initYandexSdk().then(function() {
        return loadYandexHighScore(store);
      }).catch(function(err) {
        console.error('Ошибка initYandexSdk:', err);
        loadYandexHighScore(store);
      });
    } else {
      console.log('🔄 Запуск без VK Bridge (OK или локальный режим)');
      initPromise = Promise.resolve().then(function() {
        loadYandexHighScore(store);
      });
    }
    initPromise.then(function() {
      // Проверяем локальный рекорд
      try {
        var localMax = parseInt(localStorage.getItem('tetris_high_score'), 10) || 0;
        var currentMax = store.getState().get('max') || 0;
        if (localMax > currentMax) {
          console.log('🔄 Локальный рекорд больше, сохраняем...');
          saveYandexScore(localMax);
        } else {
          console.log('✅ Рекорд синхронизирован:', currentMax);
        }
      } catch(e) { console.error('Ошибка синхронизации рекорда:', e); }

      // Синхронизация звёзд
      try {
        loadTotalScore().then(function(total) {
          console.log('⭐ Звёзды синхронизированы:', total);
        }).catch(function(err) {
          console.warn('Ошибка синхронизации звёзд:', err);
        });
      } catch(e) { console.error('Ошибка loadTotalScore:', e); }

      // Синхронизация достижений
      try {
        syncYandexAchievements().then(function() {
          console.log('✅ Достижения синхронизированы при старте');
        });
      } catch(e) { console.error('Ошибка syncYandexAchievements:', e); }

      // Подписка на изменения
      try {
        subscribeRecord(store);
      } catch(e) { console.error('Ошибка subscribeRecord:', e); }

      // Баннерная реклама
      try {
        if (typeof showBannerAd === 'function') {
          showBannerAd();
        }
      } catch(e) { console.error('Ошибка showBannerAd:', e); }

    }).catch(function(err) {
      console.error('Ошибка в initPromise:', err);
      subscribeRecord(store);
    });
  } catch(e) {
    console.error('Критическая ошибка в асинхронной инициализации:', e);
    try { subscribeRecord(store); } catch(e2) {}
  }
}, 100);


