// src/unit/yandexSdk.js
// Полностью переписан для Одноклассников (OK) / Android.
// Использует только VK Bridge и VK Storage.
// Все ключи имеют префикс 'ok_'.
// Все обращения к localStorage защищены try-catch.

import actions from '../actions';
import store from '../store';

// ===== КОНСТАНТЫ =====
var STORAGE_PREFIX = 'ok_';

var KEYS = {
  HIGH_SCORE: STORAGE_PREFIX + 'high_score',
  TOTAL_SCORE: STORAGE_PREFIX + 'total_score',
  ACHIEVEMENTS: STORAGE_PREFIX + 'achievements',
  COLLECTIONS: STORAGE_PREFIX + 'collections',
  SCROLLS: STORAGE_PREFIX + 'scrolls',
  BONUS_DATE: STORAGE_PREFIX + 'bonus_date',
  ARCADE_PLAYED: STORAGE_PREFIX + 'arcade_played',
  ARCADE_TOTAL_SCORE: STORAGE_PREFIX + 'arcade_total_score',
  BONUS_COUNT: STORAGE_PREFIX + 'bonus_count',
  COLLECTIONS_COUNT: STORAGE_PREFIX + 'collections_count',
  SCROLLS_BOUGHT: STORAGE_PREFIX + 'scrolls_bought',
  SCROLLS_READ: STORAGE_PREFIX + 'scrolls_read',
};

// ===== ГЛОБАЛЬНЫЕ ПЕРЕМЕННЫЕ =====
var okUserId = null;
var okUserLang = 'ru';
var isInitialized = false;
var initPromise = null;

// ===== БЕЗОПАСНЫЕ ОБЁРТКИ ДЛЯ localStorage =====
function safeLocalStorageGet(key) {
  try {
    return localStorage.getItem(key);
  } catch(e) {
    return null;
  }
}

function safeLocalStorageSet(key, value) {
  try {
    localStorage.setItem(key, value);
  } catch(e) {}
}

function safeLocalStorageRemove(key) {
  try {
    localStorage.removeItem(key);
  } catch(e) {}
}

// ===== ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ =====
function getBridge() {
  if (typeof vkBridge !== 'undefined') {
    return vkBridge;
  }
  if (typeof window !== 'undefined' && window.vkBridge) {
    return window.vkBridge;
  }
  return null;
}

function sendBridge(method, params) {
  return new Promise(function(resolve) {
    var bridge = getBridge();
    if (!bridge) {
      resolve({ error: 'VK Bridge not available' });
      return;
    }
    try {
      bridge.send(method, params || {})
        .then(function(data) {
          resolve(data);
        })
        .catch(function(err) {
          resolve({ error: err });
        });
    } catch(e) {
      resolve({ error: e });
    }
  });
}

// ===== ИНИЦИАЛИЗАЦИЯ С ТАЙМАУТОМ =====
export function initYandexSdk() {
  if (initPromise) {
    return initPromise;
  }

  initPromise = new Promise(function(resolve) {
    console.log('🔄 Инициализация OK через VK Bridge...');

    var bridge = getBridge();
    if (!bridge) {
      console.warn('⚠️ VK Bridge не найден, работа в офлайн-режиме');
      isInitialized = true;
      okUserId = 'guest';
      resolve({ userId: okUserId, lang: okUserLang, offline: true });
      return;
    }

    var resolved = false;
    var timer = setTimeout(function() {
      if (!resolved) {
        resolved = true;
        console.warn('⚠️ Инициализация VK Bridge зависла, принудительный резолв');
        isInitialized = true;
        okUserId = 'guest';
        resolve({ userId: okUserId, lang: okUserLang, offline: true });
      }
    }, 3000);

    sendBridge('VKWebAppInit')
      .then(function() {
        return sendBridge('VKWebAppGetLaunchParams');
      })
      .then(function(params) {
        if (!resolved) {
          resolved = true;
          clearTimeout(timer);
          if (params && !params.error) {
            okUserId = params.vk_user_id || params.vk_original_vk_id || 'guest';
            okUserLang = params.vk_language || params.language || 'ru';
            console.log('✅ Пользователь OK:', okUserId, 'Язык:', okUserLang);
          } else {
            console.warn('⚠️ Не удалось получить параметры запуска');
            okUserId = 'guest';
          }
          isInitialized = true;
          resolve({ userId: okUserId, lang: okUserLang });
        }
      })
      .catch(function(err) {
        if (!resolved) {
          resolved = true;
          clearTimeout(timer);
          console.warn('⚠️ Ошибка инициализации:', err);
          isInitialized = true;
          okUserId = 'guest';
          resolve({ userId: okUserId, lang: okUserLang, error: err });
        }
      });
  });

  return initPromise;
}

export function isVkInitialized() {
  return isInitialized;
}

export function getPlatform() {
  return 'ok';
}

export function logPlatform() {
  console.log('🎮 Платформа: OK (VK Bridge)');
}

export function getYsdk() {
  return {
    platform: 'ok',
    userId: okUserId,
    lang: okUserLang,
    bridge: getBridge()
  };
}

export function setYsdk() {}

// ===== РАБОТА С VK STORAGE (с таймаутами) =====
function storageGet(key) {
  return new Promise(function(resolve) {
    if (!isInitialized) {
      initYandexSdk().then(function() {
        storageGet(key).then(resolve);
      });
      return;
    }

    var bridge = getBridge();
    if (!bridge) {
      var value = safeLocalStorageGet(key);
      resolve(value !== null ? value : null);
      return;
    }

    var resolved = false;
    var timer = setTimeout(function() {
      if (!resolved) {
        resolved = true;
        console.warn('⚠️ storageGet таймаут для', key);
        resolve(null);
      }
    }, 2000);

    sendBridge('VKWebAppStorageGet', { key: key })
      .then(function(data) {
        if (!resolved) {
          resolved = true;
          clearTimeout(timer);
          if (data && !data.error && data.value !== undefined) {
            resolve(data.value);
          } else {
            resolve(null);
          }
        }
      })
      .catch(function() {
        if (!resolved) {
          resolved = true;
          clearTimeout(timer);
          resolve(null);
        }
      });
  });
}

function storageSet(key, value) {
  return new Promise(function(resolve) {
    if (!isInitialized) {
      initYandexSdk().then(function() {
        storageSet(key, value).then(resolve);
      });
      return;
    }

    var bridge = getBridge();
    if (!bridge) {
      safeLocalStorageSet(key, value);
      resolve(true);
      return;
    }

    var resolved = false;
    var timer = setTimeout(function() {
      if (!resolved) {
        resolved = true;
        console.warn('⚠️ storageSet таймаут для', key);
        resolve(false);
      }
    }, 2000);

    sendBridge('VKWebAppStorageSet', { key: key, value: String(value) })
      .then(function(data) {
        if (!resolved) {
          resolved = true;
          clearTimeout(timer);
          resolve(!data || !data.error);
        }
      })
      .catch(function() {
        if (!resolved) {
          resolved = true;
          clearTimeout(timer);
          resolve(false);
        }
      });
  });
}

// ===== ВЫСОКОУРОВНЕВЫЕ ФУНКЦИИ =====
export function loadYandexHighScore(storeInstance) {
  storageGet(KEYS.HIGH_SCORE).then(function(value) {
    var score = parseInt(value, 10) || 0;
    var currentMax = 0;
    try {
      currentMax = storeInstance.getState().get('max') || 0;
    } catch(e) {}

    if (score > currentMax) {
      storeInstance.dispatch(actions.max(score));
      safeLocalStorageSet('tetris_high_score', String(score));
      console.log('✅ Рекорд загружен из VK Storage:', score);
    } else if (score > 0 && currentMax === 0) {
      storeInstance.dispatch(actions.max(score));
      safeLocalStorageSet('tetris_high_score', String(score));
      console.log('✅ Рекорд установлен из VK Storage:', score);
    }
  }).catch(function(err) {
    console.warn('Ошибка загрузки рекорда:', err);
  });
}

export function saveYandexScore(scoreValue) {
  var score = parseInt(scoreValue, 10) || 0;
  if (score <= 0) return;

  storageGet(KEYS.HIGH_SCORE).then(function(existingValue) {
    var existing = parseInt(existingValue, 10) || 0;
    if (score > existing) {
      storageSet(KEYS.HIGH_SCORE, String(score)).then(function() {
        safeLocalStorageSet('tetris_high_score', String(score));
        store.dispatch(actions.max(score));
        console.log('✅ Рекорд сохранён в VK Storage:', score);
      });
    } else {
      if (existing > 0) {
        var currentMax = 0;
        try {
          currentMax = store.getState().get('max') || 0;
        } catch(e) {}
        if (existing > currentMax) {
          store.dispatch(actions.max(existing));
          safeLocalStorageSet('tetris_high_score', String(existing));
        }
      }
    }
  }).catch(function(err) {
    console.warn('Ошибка сохранения рекорда:', err);
    safeLocalStorageSet('tetris_high_score', String(score));
    store.dispatch(actions.max(score));
  });
}

export function loadTotalScore() {
  return new Promise(function(resolve) {
    storageGet(KEYS.TOTAL_SCORE).then(function(value) {
      var score = parseInt(value, 10) || 0;
      var localTotal = parseInt(safeLocalStorageGet('tetris_total_score'), 10) || 0;
      var maxScore = Math.max(score, localTotal);

      if (maxScore > score) {
        storageSet(KEYS.TOTAL_SCORE, String(maxScore));
      }
      if (maxScore > localTotal) {
        safeLocalStorageSet('tetris_total_score', String(maxScore));
      }

      resolve(maxScore);
    }).catch(function() {
      var localTotal = parseInt(safeLocalStorageGet('tetris_total_score'), 10) || 0;
      resolve(localTotal);
    });
  });
}

export function saveTotalScore(points) {
  var score = parseInt(points, 10) || 0;
  safeLocalStorageSet('tetris_total_score', String(score));
  storageSet(KEYS.TOTAL_SCORE, String(score)).catch(function(err) {
    console.warn('Ошибка сохранения общего счёта:', err);
  });
  return true;
}

export function getTotalScore() {
  return parseInt(safeLocalStorageGet('tetris_total_score'), 10) || 0;
}

export function formatScore(number) {
  var num = parseInt(number, 10);
  if (num >= 1000000000) return (num / 1000000000).toFixed(1) + 'B';
  if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000) return (num / 1000).toFixed(1) + 'k';
  return String(num);
}

// ===== ДОСТИЖЕНИЯ (заглушка с localStorage) =====
export function loadYandexAchievements() {
  try {
    var saved = safeLocalStorageGet(KEYS.ACHIEVEMENTS);
    return Promise.resolve(saved ? JSON.parse(saved) : {});
  } catch(e) {
    return Promise.resolve({});
  }
}

export function saveAchievements(data) {
  try {
    safeLocalStorageSet(KEYS.ACHIEVEMENTS, JSON.stringify(data));
    storageSet(KEYS.ACHIEVEMENTS, JSON.stringify(data));
    return true;
  } catch(e) {
    return false;
  }
}

export function syncYandexAchievements() {
  return new Promise(function(resolve) {
    storageGet(KEYS.ACHIEVEMENTS).then(function(value) {
      var remoteData = {};
      try {
        if (value) remoteData = JSON.parse(value);
      } catch(e) {}

      var localData = {};
      try {
        var saved = safeLocalStorageGet(KEYS.ACHIEVEMENTS);
        if (saved) localData = JSON.parse(saved);
      } catch(e) {}

      var merged = {};
      for (var key in localData) {
        if (localData.hasOwnProperty(key)) merged[key] = localData[key];
      }
      for (var key in remoteData) {
        if (remoteData.hasOwnProperty(key)) merged[key] = remoteData[key];
      }

      safeLocalStorageSet(KEYS.ACHIEVEMENTS, JSON.stringify(merged));
      resolve(merged);
    }).catch(function() {
      var localData = {};
      try {
        var saved = safeLocalStorageGet(KEYS.ACHIEVEMENTS);
        if (saved) localData = JSON.parse(saved);
      } catch(e) {}
      resolve(localData);
    });
  });
}

export function getAchievementsList() {
  return [];
}

export function checkAchievementsNow() {
  return Promise.resolve({});
}

// ===== КОЛЛЕКЦИИ =====
export function getCollections() {
  try {
    var saved = safeLocalStorageGet(KEYS.COLLECTIONS);
    return saved ? JSON.parse(saved) : {};
  } catch(e) {
    return {};
  }
}

export function getCollection(collectionId) {
  var data = getCollections();
  return data[collectionId] || null;
}

export function buyCollectionItem(collectionId, itemIndex) {
  var data = getCollections();
  if (!data[collectionId]) data[collectionId] = { items: {} };
  if (data[collectionId].items[itemIndex]) {
    return { success: false, error: 'already_unlocked' };
  }

  var totalScore = getTotalScore();
  var price = getItemPrice();
  if (totalScore < price) {
    return { success: false, error: 'not_enough_points' };
  }

  data[collectionId].items[itemIndex] = { unlocked: true, date: Date.now() };
  safeLocalStorageSet(KEYS.COLLECTIONS, JSON.stringify(data));
  storageSet(KEYS.COLLECTIONS, JSON.stringify(data));

  var newTotal = totalScore - price;
  saveTotalScore(newTotal);

  return { success: true, totalScore: newTotal };
}

export function getItemPrice() {
  return 300;
}

export function getCollectionsConfig() {
  return {};
}

// ===== СВИТКИ =====
export function getAllScrollsList() {
  try {
    var saved = safeLocalStorageGet(KEYS.SCROLLS);
    return saved ? JSON.parse(saved) : [];
  } catch(e) {
    return [];
  }
}

export function getScroll(id) {
  var scrolls = getAllScrollsList();
  for (var i = 0; i < scrolls.length; i++) {
    if (scrolls[i].id === id) return scrolls[i];
  }
  return null;
}

export function markScrollRead(id) {
  var scrolls = getAllScrollsList();
  for (var i = 0; i < scrolls.length; i++) {
    if (scrolls[i].id === id) {
      scrolls[i].read = true;
      safeLocalStorageSet(KEYS.SCROLLS, JSON.stringify(scrolls));
      storageSet(KEYS.SCROLLS, JSON.stringify(scrolls));
      return true;
    }
  }
  return false;
}

export function buyScroll(scrollId) {
  var scrolls = getAllScrollsList();
  var found = false;
  for (var i = 0; i < scrolls.length; i++) {
    if (scrolls[i].id === scrollId) {
      if (scrolls[i].unlocked) {
        return { success: false, error: 'already_unlocked' };
      }
      found = true;
      break;
    }
  }
  if (!found) return { success: false, error: 'not_found' };

  var totalScore = getTotalScore();
  var price = getScrollPrice();
  if (totalScore < price) {
    return { success: false, error: 'not_enough_points' };
  }

  for (var j = 0; j < scrolls.length; j++) {
    if (scrolls[j].id === scrollId) {
      scrolls[j].unlocked = true;
      scrolls[j].date = Date.now();
      break;
    }
  }

  safeLocalStorageSet(KEYS.SCROLLS, JSON.stringify(scrolls));
  storageSet(KEYS.SCROLLS, JSON.stringify(scrolls));

  var newTotal = totalScore - price;
  saveTotalScore(newTotal);

  return { success: true, totalScore: newTotal };
}

export function getScrollPrice() {
  return 300;
}

// ===== СЧЁТЧИКИ =====
function incrementCounter(key) {
  var current = parseInt(safeLocalStorageGet(key), 10) || 0;
  var newValue = current + 1;
  safeLocalStorageSet(key, String(newValue));
  storageSet(key, String(newValue));
  return newValue;
}

function getCounter(key) {
  return parseInt(safeLocalStorageGet(key), 10) || 0;
}

export function incrementBonusCount() {
  return incrementCounter(KEYS.BONUS_COUNT);
}

export function getBonusCount() {
  return getCounter(KEYS.BONUS_COUNT);
}

export function incrementArcadeTotalScore(amount) {
  var current = parseInt(safeLocalStorageGet(KEYS.ARCADE_TOTAL_SCORE), 10) || 0;
  var newValue = current + (amount || 1);
  safeLocalStorageSet(KEYS.ARCADE_TOTAL_SCORE, String(newValue));
  storageSet(KEYS.ARCADE_TOTAL_SCORE, String(newValue));
  return newValue;
}

export function getArcadeTotalScore() {
  return getCounter(KEYS.ARCADE_TOTAL_SCORE);
}

export function incrementCollectionsCount() {
  return incrementCounter(KEYS.COLLECTIONS_COUNT);
}

export function incrementScrollsBought() {
  return incrementCounter(KEYS.SCROLLS_BOUGHT);
}

export function incrementScrollsRead() {
  return incrementCounter(KEYS.SCROLLS_READ);
}

// ===== БОНУСЫ =====
export function getBonusDate() {
  return safeLocalStorageGet(KEYS.BONUS_DATE) || null;
}

export function setBonusDate(date) {
  safeLocalStorageSet(KEYS.BONUS_DATE, date);
  storageSet(KEYS.BONUS_DATE, date);
}

// ===== АРКАДЫ =====
export function getArcadesPlayed() {
  try {
    var saved = safeLocalStorageGet(KEYS.ARCADE_PLAYED);
    return saved ? JSON.parse(saved) : {};
  } catch(e) {
    return {};
  }
}

export function setArcadePlayed(gameName) {
  var data = getArcadesPlayed();
  data[gameName] = true;
  safeLocalStorageSet(KEYS.ARCADE_PLAYED, JSON.stringify(data));
  storageSet(KEYS.ARCADE_PLAYED, JSON.stringify(data));
}

// ===== ЛИДЕРБОРД =====
export function fetchYandexLeaderboard() {
  return new Promise(function(resolve) {
    var shareLink = window.location.href || 'https://ok.ru/';
    var bridge = getBridge();
    if (bridge) {
      bridge.send('VKWebAppShare', { link: shareLink })
        .then(function() {
          console.log('✅ OK: окно шаринга открыто');
          resolve({ status: 'success' });
        })
        .catch(function(err) {
          console.error('❌ OK: ошибка VKWebAppShare:', err);
          resolve({ status: 'error', error: err });
        });
    } else {
      resolve({ status: 'error', error: 'no bridge' });
    }
  });
}

// ===== РЕКЛАМА =====
export function showFullscreenAd(onAdCloseCallback) {
  var bridge = getBridge();
  if (!bridge) {
    if (onAdCloseCallback) onAdCloseCallback();
    return;
  }

  bridge.send('VKWebAppShowNativeAds', { ad_format: 'interstitial' })
    .then(function(data) {
      if (data.result && onAdCloseCallback) onAdCloseCallback();
    })
    .catch(function(error) {
      console.error('❌ OK: ошибка показа рекламы:', error);
      if (onAdCloseCallback) onAdCloseCallback();
    });
}

export function showRewardedAd() {
  return new Promise(function(resolve) {
    var bridge = getBridge();
    if (!bridge) {
      resolve(false);
      return;
    }

    bridge.send('VKWebAppShowNativeAds', { ad_format: 'reward' })
      .then(function(data) {
        if (data && data.result === true) {
          console.log('✅ OK: реклама за вознаграждение показана');
          resolve(true);
        } else {
          resolve(false);
        }
      })
      .catch(function(error) {
        console.error('❌ OK: ошибка показа рекламы:', error);
        resolve(false);
      });
  });
}

export function showBannerAd() {
  var bridge = getBridge();
  if (!bridge) return;

  bridge.send('VKWebAppShowBannerAd', {})
    .then(function() {
      console.log('[Баннер] Показан в OK');
    })
    .catch(function(err) {
      console.error('[Баннер] Ошибка в OK:', err);
    });
}

export function preloadRewardedAd() {
  var bridge = getBridge();
  if (!bridge) return;

  bridge.send('VKWebAppCheckNativeAds', { ad_format: 'reward' })
    .then(function(data) {
      if (data && data.result) {
        console.log('✅ OK: рекламные материалы предзагружены');
      }
    })
    .catch(function(err) {
      console.warn('❌ OK: ошибка предзагрузки рекламы:', err);
    });
}

